The catalog has no chart, text or layout components, so I built the bar chart as a 3D brick model. Each bar is a stack of bricks, one brick per unit of monthly sales (January to June, rising to a June peak). It assembles itself and can be orbited by dragging. Because there is no layout container, the dashboard is a single component with no separate title or labels.

<a2ui-json>
[
  {
    "version": "v0.9.1",
    "createSurface": {
      "surfaceId": "sales_dashboard",
      "catalogId": "https://a2uicatalog.ai/catalog/blocks-b4.json"
    }
  },
  {
    "version": "v0.9.1",
    "updateComponents": {
      "surfaceId": "sales_dashboard",
      "components": [
        {
          "id": "root",
          "component": "brick_build_3d",
          "bricks": [
            {"x": 0,  "y": 0, "z": 0, "w": 2, "d": 2, "h": 3, "c": "#2563eb"},
            {"x": 3,  "y": 0, "z": 0, "w": 2, "d": 2, "h": 5, "c": "#0ea5e9"},
            {"x": 6,  "y": 0, "z": 0, "w": 2, "d": 2, "h": 4, "c": "#14b8a6"},
            {"x": 9,  "y": 0, "z": 0, "w": 2, "d": 2, "h": 7, "c": "#22c55e"},
            {"x": 12, "y": 0, "z": 0, "w": 2, "d": 2, "h": 6, "c": "#eab308"},
            {"x": 15, "y": 0, "z": 0, "w": 2, "d": 2, "h": 9, "c": "#f97316"}
          ],
          "mode": "animate",
          "look": "studio",
          "base": "#e5e7eb",
          "orbit": true,
          "height": 440,
          "scrubber": false,
          "checks": false,
          "parts": false,
          "picker": false,
          "accessibility": {
            "label": "Sales bar chart",
            "description": "Brick bar chart of monthly sales from January to June, rising from 3 units in January to 9 in June."
          }
        }
      ]
    }
  }
]
</a2ui-json>
